"use client";

import Image from "next/image";
import Link from "next/link";

import clsx from "clsx";

import {
  motion,
  useReducedMotion,
} from "motion/react";

import {
  ArrowUpRight,
} from "lucide-react";

import { categories } from "@/data/site";

import styles from "./Categories.module.css";

type CategoryId =
  (typeof categories)[number]["id"];

function SectorGraphic({
  category,
}: {
  category: CategoryId;
}) {
  const reduceMotion =
    useReducedMotion();

  const pathProps = {
    initial: reduceMotion
      ? false
      : {
          pathLength: 0,
          opacity: 0,
        },

    whileInView: reduceMotion
      ? undefined
      : {
          pathLength: 1,
          opacity: 1,
        },

    viewport: {
      once: true,
      amount: 0.45,
    },

    transition: {
      duration: 1.25,
      ease: "easeOut" as const,
    },
  };

  if (category === "agricola") {
    return (
      <motion.svg
        viewBox="0 0 420 220"
        fill="none"
        className={styles.vector}
        aria-hidden="true"
      >
        {/* horizonte */}
        <motion.path
          {...pathProps}
          d="
            M16 170
            C95 124 168 126 236 165
            C292 197 344 197 404 162
          "
          className={styles.vectorSoft}
        />

        {/* surcos */}
        <motion.path
          {...pathProps}
          transition={{
            duration: 1.4,
            delay: 0.12,
          }}
          d="
            M24 194
            C104 151 170 151 237 188
          "
          className={styles.vectorSoft}
        />

        <motion.path
          {...pathProps}
          transition={{
            duration: 1.5,
            delay: 0.2,
          }}
          d="
            M88 215
            C143 181 191 179 244 207
          "
          className={styles.vectorSoft}
        />

        {/* tallo */}
        <motion.path
          {...pathProps}
          transition={{
            duration: 0.9,
            delay: 0.2,
          }}
          d="M220 166V73"
          className={styles.vectorStrong}
        />

        {/* hoja izquierda */}
        <motion.path
          {...pathProps}
          transition={{
            duration: 0.9,
            delay: 0.42,
          }}
          d="
            M220 113
            C191 111 168 94 160 66
            C190 65 213 83 220 113Z
          "
          className={styles.vectorFill}
        />

        {/* hoja derecha */}
        <motion.path
          {...pathProps}
          transition={{
            duration: 0.9,
            delay: 0.58,
          }}
          d="
            M220 139
            C248 132 269 111 278 85
            C248 86 227 105 220 139Z
          "
          className={styles.vectorFill}
        />

        <motion.circle
          cx="220"
          cy="166"
          r="5"
          className={styles.vectorDot}
          initial={
            reduceMotion
              ? false
              : {
                  scale: 0,
                }
          }
          whileInView={
            reduceMotion
              ? undefined
              : {
                  scale: 1,
                }
          }
          viewport={{
            once: true,
          }}
          transition={{
            duration: 0.45,
            delay: 0.8,
          }}
        />
      </motion.svg>
    );
  }

  if (category === "construccion") {
    return (
      <motion.svg
        viewBox="0 0 420 220"
        fill="none"
        className={styles.vector}
        aria-hidden="true"
      >
        {/* terreno */}
        <motion.path
          {...pathProps}
          d="
            M20 183
            H398
          "
          className={styles.vectorSoft}
        />

        {/* cuerpo excavadora */}
        <motion.path
          {...pathProps}
          d="
            M110 168
            H225
            L247 181
            H101
            Z
          "
          className={styles.vectorFill}
        />

        {/* cabina */}
        <motion.path
          {...pathProps}
          transition={{
            duration: 1,
            delay: 0.15,
          }}
          d="
            M147 168
            L158 124
            H207
            L224 168
          "
          className={styles.vectorStrong}
        />

        {/* brazo */}
        <motion.path
          {...pathProps}
          transition={{
            duration: 1.15,
            delay: 0.28,
          }}
          d="
            M208 130
            L272 93
            L328 112
          "
          className={styles.vectorStrong}
        />

        {/* brazo final */}
        <motion.path
          {...pathProps}
          transition={{
            duration: 1,
            delay: 0.5,
          }}
          d="
            M328 112
            L361 143
          "
          className={styles.vectorStrong}
        />

        {/* pala */}
        <motion.path
          {...pathProps}
          transition={{
            duration: 0.8,
            delay: 0.68,
          }}
          d="
            M361 143
            L390 154
            L374 176
            L344 164
            Z
          "
          className={styles.vectorFill}
        />

        {/* ruedas/orugas */}
        <motion.circle
          cx="132"
          cy="184"
          r="16"
          className={styles.vectorStrong}
          {...pathProps}
        />

        <motion.circle
          cx="203"
          cy="184"
          r="16"
          className={styles.vectorStrong}
          {...pathProps}
        />

        {/* marcas de obra */}
        <motion.path
          {...pathProps}
          transition={{
            duration: 1.1,
            delay: 0.65,
          }}
          d="
            M292 42V70
            M278 56H306
          "
          className={styles.vectorSoft}
        />
      </motion.svg>
    );
  }

  return (
    <motion.svg
      viewBox="0 0 420 220"
      fill="none"
      className={styles.vector}
      aria-hidden="true"
    >
      {/* engranaje */}
      <motion.circle
        cx="215"
        cy="112"
        r="59"
        className={styles.vectorStrong}
        {...pathProps}
      />

      <motion.circle
        cx="215"
        cy="112"
        r="24"
        className={styles.vectorStrong}
        {...pathProps}
      />

      {/* dientes */}
      {Array.from({
        length: 8,
      }).map((_, index) => {
        const angle =
          index * 45;

        const radians =
          (angle * Math.PI) / 180;

        const x =
          215 +
          Math.cos(radians) * 78;

        const y =
          112 +
          Math.sin(radians) * 78;

        return (
          <motion.rect
            key={angle}
            x={x - 9}
            y={y - 17}
            width="18"
            height="34"
            rx="2"
            transform={`
              rotate(
                ${angle}
                ${x}
                ${y}
              )
            `}
            className={styles.vectorFill}
            initial={
              reduceMotion
                ? false
                : {
                    opacity: 0,
                    scale: 0.6,
                  }
            }
            whileInView={
              reduceMotion
                ? undefined
                : {
                    opacity: 1,
                    scale: 1,
                  }
            }
            viewport={{
              once: true,
            }}
            transition={{
              duration: 0.4,
              delay:
                0.08 * index,
            }}
          />
        );
      })}

      {/* conexiones */}
      <motion.path
        {...pathProps}
        d="
          M30 112
          H127
        "
        className={styles.vectorSoft}
      />

      <motion.path
        {...pathProps}
        d="
          M303 112
          H390
        "
        className={styles.vectorSoft}
      />

      <motion.circle
        cx="30"
        cy="112"
        r="5"
        className={styles.vectorDot}
      />

      <motion.circle
        cx="390"
        cy="112"
        r="5"
        className={styles.vectorDot}
      />
    </motion.svg>
  );
}

export default function Categories() {
  const reduceMotion =
    useReducedMotion();

  return (
    <section
      className={styles.section}
      aria-labelledby="categories-title"
    >
      {/* =========================================
          BACKGROUND
      ========================================== */}

      <div
        className={styles.background}
        aria-hidden="true"
      >
        <span
          className={
            styles.backgroundNumber
          }
        >
          02
        </span>

        <i
          className={
            styles.backgroundLine
          }
        />
      </div>

      <div className="morgillo-container">
        {/* =========================================
            HEADER
        ========================================== */}

        <div className={styles.header}>
          <div>
            <div className={styles.eyebrow}>
              <span>02</span>

              <i />

              <p>
                Líneas de trabajo
              </p>
            </div>

            <h2 id="categories-title">
              Cada operación exige
              <span>
                {" "}
                una solución diferente.
              </span>
            </h2>
          </div>

          <div className={styles.intro}>
            <span>
              CAMPO / OBRA / EQUIPAMIENTO
            </span>

            <p>
              Explora la maquinaria según el
              tipo de trabajo y encuentra la
              solución adecuada para tu
              operación.
            </p>
          </div>
        </div>

        {/* =========================================
            CARDS
        ========================================== */}

        <div className={styles.grid}>
          {categories.map(
            (category, index) => (
              <motion.article
                key={category.id}
                className={clsx(
                  styles.card,
                  styles[
                    `card-${category.id}`
                  ],
                )}
                initial={
                  reduceMotion
                    ? false
                    : {
                        opacity: 0,
                        y: 32,
                      }
                }
                whileInView={
                  reduceMotion
                    ? undefined
                    : {
                        opacity: 1,
                        y: 0,
                      }
                }
                viewport={{
                  once: true,
                  amount: 0.15,
                }}
                transition={{
                  duration: 0.55,
                  delay:
                    index * 0.08,
                  ease: [
                    0.16,
                    1,
                    0.3,
                    1,
                  ],
                }}
              >
                <Link
                  href={`/maquinaria?categoria=${category.id}`}
                  className={styles.link}
                >
                  {/* ===============================
                      PHOTO
                  ================================ */}

                  <div className={styles.media}>
                    <Image
                      src={category.image}
                      alt={category.name}
                      fill
                      sizes="
                        (max-width: 640px) 100vw,
                        (max-width: 960px) 50vw,
                        33vw
                      "
                      className={styles.image}
                    />

                    <div
                      className={styles.overlay}
                    />

                    <span
                      className={
                        styles.index
                      }
                    >
                      {String(
                        index + 1,
                      ).padStart(
                        2,
                        "0",
                      )}
                    </span>

                    <span
                      className={
                        styles.mediaLabel
                      }
                    >
                      {category.brand}
                    </span>
                  </div>

                  {/* ===============================
                      VECTOR
                  ================================ */}

                  <div
                    className={
                      styles.graphic
                    }
                  >
                    <SectorGraphic
                      category={
                        category.id
                      }
                    />

                    <span
                      className={
                        styles.graphicLabel
                      }
                    >
                      {category.id ===
                        "agricola" &&
                        "Campo"}

                      {category.id ===
                        "construccion" &&
                        "Obra"}

                      {category.id ===
                        "implementos" &&
                        "Mecánica"}
                    </span>
                  </div>

                  {/* ===============================
                      CONTENT
                  ================================ */}

                  <div
                    className={
                      styles.content
                    }
                  >
                    <div
                      className={
                        styles.contentTop
                      }
                    >
                      <span>
                        Línea Morgillo
                      </span>

                      <span
                        className={
                          styles.arrow
                        }
                      >
                        <ArrowUpRight
                          size={18}
                          strokeWidth={
                            1.7
                          }
                        />
                      </span>
                    </div>

                    <h3>
                      {category.name}
                    </h3>

                    <p>
                      {
                        category.description
                      }
                    </p>

                    <div
                      className={
                        styles.footer
                      }
                    >
                      <span />

                      <strong>
                        Explorar equipos
                      </strong>
                    </div>
                  </div>
                </Link>
              </motion.article>
            ),
          )}
        </div>

        {/* =========================================
            BOTTOM RAIL
        ========================================== */}

        <div className={styles.bottom}>
          <div>
            <span />

            <strong>
              MORGILLO
            </strong>

            <p>
              Soluciones según tu tipo de trabajo
            </p>
          </div>

          <Link href="/maquinaria">
            Ver toda la maquinaria

            <ArrowUpRight
              size={16}
              strokeWidth={1.8}
            />
          </Link>
        </div>
      </div>
    </section>
  );
}